// Return visits are stored separately from public study notes and protected by the shared PIN.
let visitsOwner='',visitsBook=null,visitsActiveId='',visitsSearch='',visitsSearchOpen=false,visitsArchived=false,visitsLoadToken=0;
const visitsRoute=()=>location.hash==='#/ministry/visits';
function visitsRouteGuard(){const d=document.querySelector('.visits-dialog[open]');if(visitsRoute()||!d)return true;if(d.dataset.busy==='true'){history.replaceState(history.state,'',location.pathname+location.search+'#/ministry/visits');return false}if(d.isDirty?.()&&!confirm('작성 중인 내용을 그만둘까요?')){history.replaceState(history.state,'',location.pathname+location.search+'#/ministry/visits');return false}d.close();return true}
function visitsView(){if(!ministryPin){location.hash='#/ministry';return}visitsOwner=ministryPerson;visitsActiveId='';visitsSearch='';visitsSearchOpen=false;visitsArchived=false;visitsLoad()}
async function visitsLoad(){const owner=visitsOwner,token=++visitsLoadToken;showCoupleLoading();try{const r=await rpc('study_visits_read',{p_password:ministryPin,p_person:owner});if(!r?.ok)throw Error(r?.error||'불러오지 못했어요.');if(!visitsRoute()||token!==visitsLoadToken)return;visitsBook={entries:r.entries||[],revision:r.revision};visitsRender()}catch(err){if(!visitsRoute()||token!==visitsLoadToken)return;$('#app').innerHTML=`<div class="notice" role="alert">${esc(err.message||'불러오지 못했어요.')} <button class="link" id="visits-retry">다시 시도</button></div><a class="back bottom-back" href="#/ministry">← 야외 봉사</a>`;$('#visits-retry').onclick=visitsLoad}}
function visitsDate(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value||''))return '';const [y,m,d]=value.split('-').map(Number),date=new Date(y,m-1,d,12);return `${m}월 ${d}일 · ${['일','월','화','수','목','금','토'][date.getDay()]}요일`}
function visitsRender(){if(!visitsBook||!visitsRoute())return;if(visitsActiveId){const entry=visitsBook.entries.find(e=>e.id===visitsActiveId);if(entry){visitsDetail(entry);return}visitsActiveId=''}visitsList()}
function visitsStopped(entry){const list=entry.visits||[];if(!list.length)return false;const sorted=list.map((v,i)=>({v,i})).sort((a,b)=>String(b.v.date).localeCompare(String(a.v.date))||b.i-a.i);return sorted[0].v.outcome==='stop'}
function visitsList(){const entries=visitsBook.entries.filter(e=>!!e.archived===visitsArchived),q=visitsSearch.trim().toLocaleLowerCase(),filtered=entries.filter(e=>[e.name,e.address,e.next_topic].some(v=>String(v||'').toLocaleLowerCase().includes(q))).sort((a,b)=>{if(visitsStopped(a)!==visitsStopped(b))return visitsStopped(a)?1:-1;if(!a.next_date)return b.next_date?1:(a.name||'').localeCompare(b.name||'','ko');if(!b.next_date)return -1;return a.next_date.localeCompare(b.next_date)||(a.name||'').localeCompare(b.name||'','ko')});const today=todayLocal().month+'-'+String(todayLocal().day).padStart(2,'0');
 $('#app').innerHTML=`<div class="workspace visits-page"><header class="visits-head"><h1 class="people-title">재방문</h1><div class="visits-head-actions"><button class="action-icon" id="visits-search-toggle" aria-label="검색" title="검색">${uiIcon('<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>')}</button><button class="action-icon" id="visits-add" aria-label="사람 추가" title="사람 추가">${UI_PLUS}</button></div></header><div id="visits-search-wrap" ${visitsSearchOpen?'':'hidden'}><input id="visits-search" type="search" placeholder="이름, 주소, 주제" aria-label="재방문 검색" value="${esc(visitsSearch)}"></div><div class="visits-list">${filtered.length?['예정','날짜 미정','방문 중단'].map(group=>{const items=filtered.filter(e=>visitsStopped(e)?group==='방문 중단':e.next_date?group==='예정':group==='날짜 미정');return items.length?`<h2 class="visits-group-title">${group}</h2>${items.map(e=>`<button type="button" class="visits-row" data-visit-id="${esc(e.id)}"><span class="visits-row-main"><strong>${esc(e.name||'이름 없음')}</strong><small>${esc(e.next_topic||'')}</small></span><span class="visits-row-date ${!visitsStopped(e)&&e.next_date&&e.next_date<today?'is-overdue':''}">${esc(!visitsStopped(e)&&e.next_date?visitsDate(e.next_date):'')}</span></button>`).join('')}`:''}).join(''):`<p class="visits-empty">${q?'검색 결과가 없어요.':visitsArchived?'보관한 기록이 없어요.':'재방문 기록이 없어요.'}</p>`}</div><button type="button" class="visits-archive-toggle" id="visits-archive-toggle">${visitsArchived?'현재 목록':'보관한 기록'}</button></div><a class="back bottom-back" href="#/ministry">← 야외 봉사</a>`;
 $('#visits-add').onclick=visitsAdd;$('#visits-search-toggle').onclick=()=>{const wrap=$('#visits-search-wrap');visitsSearchOpen=!visitsSearchOpen;wrap.hidden=!visitsSearchOpen;if(visitsSearchOpen)$('#visits-search').focus();else if(visitsSearch){visitsSearch='';visitsList()}};$('#visits-search').oninput=e=>{const value=e.target.value,pos=e.target.selectionStart;visitsSearch=value;visitsList();const n=$('#visits-search');n.focus();n.setSelectionRange(pos,pos)};$('#visits-archive-toggle').onclick=()=>{visitsArchived=!visitsArchived;visitsList()};document.querySelectorAll('[data-visit-id]').forEach(b=>b.onclick=()=>{visitsActiveId=b.dataset.visitId;visitsRender()})}
function visitsDetail(entry){const fields=[['next_date','다음 방문',entry.next_date?visitsDate(entry.next_date):'날짜 정하기'],['next_topic','다음 이야기',entry.next_topic||'내용 추가'],['address','주소',entry.address||'주소 추가'],['age','연령대',entry.age||'선택'],['preferred','편한 시간',entry.preferred||'시간 추가']];const list=[...(entry.visits||[])].sort((a,b)=>String(b.date).localeCompare(String(a.date)));
 $('#app').innerHTML=`<div class="workspace visits-page visits-detail"><header class="visits-detail-head"><button type="button" class="visits-title" data-field="name">${esc(entry.name)}</button><button type="button" class="action-icon" id="visits-menu" aria-label="더 보기" title="더 보기">${uiIcon('<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>')}</button></header>${visitsStopped(entry)?'<p class="visits-stopped">방문 중단</p>':''}<div class="visits-details">${fields.map(([key,label,value])=>`<button type="button" class="visits-field" data-field="${key}"><span>${label}</span><strong class="${!entry[key]?'is-empty':''}">${esc(value)}</strong></button>`).join('')}</div><div class="visits-history-head"><h2>방문 기록</h2><button type="button" id="visits-log-add" class="action-icon" aria-label="방문 기록 추가" title="방문 기록 추가">${UI_PLUS}</button></div><div class="visits-history">${list.length?list.map(v=>`<button type="button" class="visits-log" data-log-id="${esc(v.id)}"><span class="visits-log-date">${esc(visitsDate(v.date)||v.date)}${v.outcome==='away'?' · 만나지 못함':v.outcome==='stop'?' · 방문하지 않음':''}</span>${v.note?`<span>${esc(v.note)}</span>`:''}${v.scripture?`<small>${esc(v.scripture)}</small>`:''}</button>`).join(''):'<p class="visits-empty">방문 기록이 없어요.</p>'}</div></div><button class="back bottom-back visits-back" type="button">← 재방문</button>`;
 document.querySelectorAll('[data-field]').forEach(b=>b.onclick=()=>visitsEditField(entry,b.dataset.field));$('#visits-menu').onclick=()=>visitsMenu(entry);$('#visits-log-add').onclick=()=>visitsLogForm(entry);document.querySelectorAll('[data-log-id]').forEach(b=>b.onclick=()=>visitsLogForm(entry,(entry.visits||[]).find(v=>v.id===b.dataset.logId)));$('.visits-back').onclick=()=>{visitsActiveId='';visitsRender()}}
function visitsDialog(title,content){const d=document.createElement('dialog');d.className='family-dialog visits-dialog';d.innerHTML=`<div class="family-sheet"><div class="family-sheet-head"><h2>${esc(title)}</h2><button type="button" class="tool-icon family-dialog-close" aria-label="닫기">${uiIcon('<path d="M18 6 6 18M6 6l12 12"/>')}</button></div>${content}</div>`;document.body.append(d);d.safeClose=()=>{if(d.dataset.busy==='true')return;if(!d.isDirty?.()||confirm('작성 중인 내용을 그만둘까요?'))d.close()};d.querySelector('.family-dialog-close').onclick=()=>d.safeClose();d.addEventListener('cancel',e=>{e.preventDefault();d.safeClose()});d.addEventListener('close',()=>d.remove(),{once:true});d.showModal();return d}
async function visitsSave(d,transform,onSuccess){if(d.dataset.busy==='true')return;const owner=visitsOwner,revision=visitsBook.revision,entries=structuredClone(visitsBook.entries);let next;try{next=transform(entries)}catch(err){d.querySelector('.family-form-error').textContent=err.message;return}d.dataset.busy='true';d.querySelectorAll('button,input,textarea,select').forEach(b=>b.disabled=true);const error=d.querySelector('.family-form-error');error.textContent='';try{const r=await rpc('study_visits_write',{p_password:ministryPin,p_person:owner,p_revision:revision,p_entries:next});if(!r?.ok){if(r?.conflict){error.textContent='다른 기기에서 기록이 바뀌었어요. 작성한 내용을 확인한 뒤 최신 목록을 다시 열어 주세요.';const refresh=document.createElement('button');refresh.type='button';refresh.textContent='최신 목록 열기';refresh.onclick=async()=>{if(!confirm('작성 중인 내용은 저장되지 않아요. 최신 목록을 열까요?'))return;d.isDirty=()=>false;d.close();await visitsLoad()};error.append(' ',refresh);return}throw Error(r?.error||'저장하지 못했어요.')}visitsBook={entries:next,revision:r.revision};onSuccess?.();d.isDirty=()=>false;d.close();if(visitsRoute()&&visitsOwner===owner)visitsRender()}catch(err){error.textContent=err.message||'저장하지 못했어요. 연결을 확인한 뒤 다시 시도해 주세요.'}finally{d.dataset.busy='false';if(d.isConnected)d.querySelectorAll('button,input,textarea,select').forEach(b=>b.disabled=false)}}
function visitsAdd(){const d=visitsDialog('재방문 추가',`<form class="family-form"><label class="family-field">이름 또는 호칭<input name="name" maxlength="100" required autocomplete="off"></label><label class="family-field">다음 방문일<input name="next_date" type="date"></label><label class="family-field">간단한 메모<textarea name="note" rows="2" maxlength="3000"></textarea></label><p class="family-form-error" role="alert"></p><button class="primary family-save" type="submit">저장</button></form>`),f=d.querySelector('form');d.isDirty=()=>!!(f.elements.name.value||f.next_date.value||f.note.value);f.onsubmit=e=>{e.preventDefault();const name=f.elements.name.value.trim();if(!name)return;const id=crypto.randomUUID(),note=f.note.value.trim();visitsSave(d,items=>{items.push({id,name,next_date:f.next_date.value,next_topic:note,address:'',age:'',preferred:'',archived:false,visits:[]});return items},()=>{visitsActiveId=id})}}
function visitsEditField(entry,key){const config={name:['이름 또는 호칭','text',100],next_date:['다음 방문','date',0],next_topic:['다음 이야기','textarea',3000],address:['주소','textarea',1000],age:['연령대','text',80],preferred:['편한 시간','text',200]}[key];if(!config)return;const [label,type,max]=config,value=String(entry[key]||''),control=type==='textarea'?`<textarea name="value" rows="3" maxlength="${max}">${esc(value)}</textarea>`:`<input name="value" type="${type}" value="${esc(value)}" ${max?`maxlength="${max}"`:''} ${key==='name'?'required':''}>`;const d=visitsDialog(label,`<form class="family-form"><label class="family-field"><span class="sr-only">${label}</span>${control}</label><p class="family-form-error" role="alert"></p><button class="primary family-save" type="submit">저장</button></form>`),f=d.querySelector('form');d.isDirty=()=>f.elements.value.value!==value;f.onsubmit=e=>{e.preventDefault();const v=f.elements.value.value.trim();if(key==='name'&&!v)return;visitsSave(d,items=>{const target=items.find(x=>x.id===entry.id);if(!target)throw Error('이 기록을 찾지 못했어요.');target[key]=v;return items})}}
function visitsLogForm(entry,old=null){const today=todayLocal().month+'-'+String(todayLocal().day).padStart(2,'0'),log=old||{id:crypto.randomUUID(),date:today,outcome:'talk',note:'',scripture:''};const d=visitsDialog(old?'방문 기록':'방문 기록 추가',`<form class="family-form"><label class="family-field">방문일<input type="date" name="date" value="${esc(log.date)}" required></label><label class="family-field">결과<select name="outcome"><option value="talk">대화함</option><option value="away">만나지 못함</option><option value="stop">다음에 방문하지 않음</option></select></label><label class="family-field">대화<textarea name="note" rows="3" maxlength="3000">${esc(log.note||'')}</textarea></label><label class="family-field">성구·자료<input name="scripture" maxlength="300" value="${esc(log.scripture||'')}"></label><label class="family-field">다음에 나눌 내용<textarea name="next_topic" rows="2" maxlength="3000">${esc(entry.next_topic||'')}</textarea></label><label class="family-field">다음 방문일<input name="next_date" type="date" value="${esc(entry.next_date||'')}"></label><p class="family-form-error" role="alert"></p><button class="primary family-save" type="submit">저장</button>${old?'<button type="button" class="visits-delete-log">방문 기록 삭제</button>':''}</form>`),f=d.querySelector('form');f.outcome.value=log.outcome||'talk';const snap=()=>JSON.stringify([f.date.value,f.outcome.value,f.note.value,f.scripture.value,f.next_topic.value,f.next_date.value]);const initial=snap();d.isDirty=()=>snap()!==initial;f.onsubmit=e=>{e.preventDefault();const updated={id:log.id,date:f.date.value,outcome:f.outcome.value,note:f.note.value.trim(),scripture:f.scripture.value.trim()};visitsSave(d,items=>{const target=items.find(x=>x.id===entry.id);if(!target)throw Error('이 기록을 찾지 못했어요.');target.visits=target.visits||[];const ix=target.visits.findIndex(x=>x.id===log.id);if(ix<0)target.visits.push(updated);else target.visits[ix]=updated;target.next_topic=f.next_topic.value.trim();target.next_date=f.next_date.value;return items})};d.querySelector('.visits-delete-log')?.addEventListener('click',()=>{if(!confirm('이 방문 기록을 삭제할까요?'))return;visitsSave(d,items=>{const target=items.find(x=>x.id===entry.id);target.visits=(target.visits||[]).filter(x=>x.id!==log.id);return items})})}
function visitsMenu(entry){const d=visitsDialog('더 보기',`<div class="family-photo-actions"><button type="button" data-archive>${entry.archived?'보관 해제':'보관'}</button><button type="button" data-delete>삭제</button></div><p class="family-form-error" role="alert"></p>`);d.querySelector('[data-archive]').onclick=()=>visitsSave(d,items=>{items.find(x=>x.id===entry.id).archived=!entry.archived;return items},()=>{visitsActiveId=''});d.querySelector('[data-delete]').onclick=()=>{if(!confirm('이 사람과 모든 방문 기록을 삭제할까요?'))return;visitsSave(d,items=>{return items.filter(x=>x.id!==entry.id)},()=>{visitsActiveId=''})}}

window.addEventListener('beforeunload',event=>{const d=document.querySelector('.visits-dialog[open]');if(d&&(d.dataset.busy==='true'||d.isDirty?.())){event.preventDefault();event.returnValue=''}});
